const items = $input.all();

return items.map((item, index) => {
  const data = item.json;
  const snippet = data.snippet || {};

  const videoId =
    data.id ||
    snippet.resourceId?.videoId ||
    data.contentDetails?.videoId ||
    "";

  const validVideoId =
    typeof videoId === "string" &&
    /^[a-zA-Z0-9_-]{11}$/.test(videoId);

  return {
    json: {
      serial_number: index + 1,

      video_id: validVideoId ? videoId : "",

      video_url: validVideoId
        ? `https://www.youtube.com/watch?v=${videoId}`
        : "",

      title: snippet.title || "Unknown Title",

      description: snippet.description || "",

      channel_id: snippet.channelId || "",

      channel_title: snippet.channelTitle || "",

      published_at: snippet.publishedAt || "",

      thumbnail:
        snippet.thumbnails?.high?.url ||
        snippet.thumbnails?.medium?.url ||
        snippet.thumbnails?.default?.url ||
        "",

      status: validVideoId
        ? "Ready for Processing"
        : "Missing Video ID"
    }
  };
});

// YouTube Transcript Data Refinement
// n8n Code Node - Run Once for All Items

const items = $input.all();

return items.map((item, index) => {
  const data = item.json;

  // 1. Get transcript segments
  const segments = Array.isArray(data.transcript)
    ? data.transcript
    : [];

  // 2. Extract and clean transcript
  const cleanedSegments = segments
    .map(segment => {
      const text = String(segment.text || "")
        .replace(/\r?\n/g, " ")
        .replace(/\s+/g, " ")
        .trim();

      return {
        text,
        start: Number(segment.start) || 0,
        duration: Number(segment.duration) || 0
      };
    })
    .filter(segment => segment.text.length > 0);

  // 3. Combine full transcript
  const fullTranscript = cleanedSegments
    .map(segment => segment.text)
    .join(" ");

  // 4. Word count
  const wordCount = fullTranscript
    .split(/\s+/)
    .filter(Boolean)
    .length;

  // 5. Quality validation
  const isValid = wordCount >= 50;

  // 6. Text chunks for long videos
  const maxChunkCharacters = 12000;
  const chunks = [];

  let currentChunk = "";

  for (const segment of cleanedSegments) {
    const nextText = segment.text;

    if (
      currentChunk.length + nextText.length + 1 >
      maxChunkCharacters &&
      currentChunk.length > 0
    ) {
      chunks.push(currentChunk.trim());
      currentChunk = "";
    }

    currentChunk += (currentChunk ? " " : "") + nextText;
  }

  if (currentChunk.trim()) {
    chunks.push(currentChunk.trim());
  }

  // 7. Structured output
  return {
    json: {
      video_id: data.video_id || "",
      video_url: data.video_id
        ? `https://www.youtube.com/watch?v=${data.video_id}`
        : "",

      language: data.language || "unknown",

      transcript: fullTranscript,
      transcript_chunks: chunks,

      word_count: wordCount,
      segment_count: cleanedSegments.length,
      chunk_count: chunks.length,

      duration_seconds:
        Number(data.length_seconds) || 0,

      validation: {
        is_valid: isValid,
        status: isValid
          ? "Ready for AI Analysis"
          : "Insufficient Transcript Data"
      },

      processed_at: new Date().toISOString()
    }
  };
});

const items = $input.all();

// Update this if your earlier node has a different name.
const sourceItems = $("Refind data from summarization for ai agent").all();

function parseAI(value) {
  if (value && typeof value === "object") return value;

  if (typeof value !== "string") {
    throw new Error("AI output missing");
  }

  const clean = value
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  return JSON.parse(clean);
}

function str(value) {
  return typeof value === "string" ? value.trim() : "";
}

function arr(value) {
  return Array.isArray(value)
    ? value.map(str).filter(Boolean)
    : [];
}

function escapeHTML(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function listHTML(values) {
  if (!values.length) {
    return "<p>Not available</p>";
  }

  return "<ul>" + values
    .map(v => `<li>${escapeHTML(v)}</li>`)
    .join("") + "</ul>";
}

return items.map((item, index) => {
  const ai = parseAI(item.json.output ?? item.json);

  // Metadata from transcript refinement node
  const source = sourceItems[index]?.json || {};

  const videoId = str(source.video_id);
  const videoUrl = videoId
    ? `https://www.youtube.com/watch?v=${videoId}`
    : "";

  const title = str(source.title) ||
    str(ai.main_topic) ||
    "YouTube Video";

  const report = {
    video_id: videoId,
    video_url: videoUrl,
    video_title: title,
    language: str(source.language),

    main_topic: str(ai.main_topic),
    category: str(ai.category),
    short_summary: str(ai.short_summary),
    detailed_summary: str(ai.detailed_summary),

    subtopics: arr(ai.subtopics),
    key_points: arr(ai.key_points),
    important_insights: arr(ai.important_insights),
    actionable_takeaways: arr(ai.actionable_takeaways),
    keywords: arr(ai.keywords),
    speaker_claims: arr(ai.speaker_claims),

    target_audience: str(ai.target_audience),
    conclusion: str(ai.conclusion),
    limitations: arr(ai.limitations)
  };

  if (!report.main_topic || !report.short_summary) {
    throw new Error(`Missing required summary: item ${index + 1}`);
  }

  const section = (heading, content) => `
    <section style="margin:24px 0">
      <h2 style="font-size:18px;color:#1e3a5f;
                 border-bottom:1px solid #ddd;
                 padding-bottom:8px">
        ${escapeHTML(heading)}
      </h2>
      ${content}
    </section>
  `;

  const paragraph = value =>
    `<p style="line-height:1.7;white-space:pre-wrap">
      ${escapeHTML(value || "Not available")}
    </p>`;

  const emailHTML = `
  <div style="background:#f3f6fa;padding:24px;
              font-family:Arial,sans-serif;color:#263238">

    <div style="max-width:720px;margin:auto;
                background:#fff;border-radius:12px;
                padding:30px">

      <h1 style="color:#17365d;margin-bottom:8px">
        YouTube Video Research Report
      </h1>

      <p style="color:#777">
        Human Review Required
      </p>

      <p>
        <strong>Video:</strong>
        ${escapeHTML(title)}
      </p>

      <p>
        <strong>Main Topic:</strong>
        ${escapeHTML(report.main_topic)}
      </p>

      <p>
        <strong>Category:</strong>
        ${escapeHTML(report.category)}
      </p>

      ${videoUrl ? `
        <p>
          <a href="${escapeHTML(videoUrl)}"
             style="color:#1565c0">
            Watch Original Video
          </a>
        </p>
      ` : ""}

      ${section("Executive Summary",
        paragraph(report.short_summary))}

      ${section("Detailed Summary",
        paragraph(report.detailed_summary))}

      ${section("Key Points",
        listHTML(report.key_points))}

      ${section("Important Insights",
        listHTML(report.important_insights))}

      ${section("Actionable Takeaways",
        listHTML(report.actionable_takeaways))}

      ${section("Speaker Claims",
        listHTML(report.speaker_claims))}

      ${section("Keywords",
        paragraph(report.keywords.join(", ")))}

      ${section("Conclusion",
        paragraph(report.conclusion))}

      ${section("Limitations",
        listHTML(report.limitations))}

      <div style="background:#fff8e1;
                  padding:18px;border-radius:8px;
                  margin-top:25px">
        <strong>Review Required</strong>
        <p>
          Please review the accuracy, completeness
          and quality of this AI-generated report.
        </p>
        <p>
          Use the approval controls provided
          by the n8n review email.
        </p>
      </div>

      <p style="font-size:12px;color:#888;
                margin-top:28px">
        AI-generated report. Human verification required.
      </p>

    </div>
  </div>`;

  return {
    json: {
      ...report,

      key_points_text: report.key_points.join("\n"),
      keywords_text: report.keywords.join(", "),
      insights_text: report.important_insights.join("\n"),

      review_status: "Pending Approval",
      validation_status: "Validated",
      processed_at: new Date().toISOString(),

      email_subject:
        `Review Required: ${report.main_topic}`,

      email_html: emailHTML
    }
  };
});

// FINAL REFINEMENT 2
// Revised YouTube Summary for Human Reapproval

const items = $input.all();

// Original video data
const sourceItems = $(
  "Refind data from summarization for ai agent"
).all();

// Original approved/rejected report
const originalReports = $("Final Refinement").all();

function parseAI(value) {
  if (value && typeof value === "object") {
    return value;
  }

  if (typeof value !== "string") {
    throw new Error("Revised AI output is missing");
  }

  const cleaned = value
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  return JSON.parse(cleaned);
}

function cleanText(value) {
  return typeof value === "string"
    ? value.trim()
    : "";
}

function cleanArray(value) {
  return Array.isArray(value)
    ? value
        .filter(v => typeof v === "string")
        .map(v => v.trim())
        .filter(Boolean)
    : [];
}

function escapeHTML(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function htmlList(values) {
  if (!values.length) {
    return "<p>Not available</p>";
  }

  return `
    <ul>
      ${values.map(value =>
        `<li>${escapeHTML(value)}</li>`
      ).join("")}
    </ul>
  `;
}

return items.map((item, index) => {

  // Get revised AI response
  const ai = parseAI(
    item.json.output ?? item.json
  );

  const source = sourceItems[index]?.json || {};
  const original = originalReports[index]?.json || {};

  const videoId = cleanText(
    source.video_id || original.video_id
  );

  const videoUrl = videoId
    ? `https://www.youtube.com/watch?v=${videoId}`
    : cleanText(original.video_url);

  const title =
    cleanText(original.video_title) ||
    cleanText(source.title) ||
    "YouTube Video";

  // Revised report
  const revised = {
    video_id: videoId,
    video_url: videoUrl,
    video_title: title,

    main_topic: cleanText(ai.main_topic),
    category: cleanText(ai.category),

    short_summary: cleanText(ai.short_summary),
    detailed_summary: cleanText(ai.detailed_summary),

    subtopics: cleanArray(ai.subtopics),
    key_points: cleanArray(ai.key_points),

    important_insights:
      cleanArray(ai.important_insights),

    actionable_takeaways:
      cleanArray(ai.actionable_takeaways),

    keywords: cleanArray(ai.keywords),

    speaker_claims:
      cleanArray(ai.speaker_claims),

    target_audience:
      cleanText(ai.target_audience),

    conclusion:
      cleanText(ai.conclusion),

    limitations:
      cleanArray(ai.limitations)
  };

  // Validate revised summary
  if (
    !revised.main_topic ||
    !revised.short_summary
  ) {
    throw new Error(
      `Revised summary missing required fields: item ${index + 1}`
    );
  }

  // Original summary for comparison
  const originalSummary =
    cleanText(original.short_summary);

  // Professional email content
  const emailHTML = `
  <div style="
    background:#f3f6fa;
    padding:25px;
    font-family:Arial,sans-serif;
    color:#263238;
  ">

    <div style="
      max-width:720px;
      margin:auto;
      background:white;
      padding:30px;
      border-radius:12px;
    ">

      <h1 style="color:#17365d">
        YouTube Summary — Revised Report
      </h1>

      <p style="color:#b45309">
        Human Reapproval Required
      </p>

      <h2>Video Information</h2>

      <p><strong>Title:</strong>
        ${escapeHTML(title)}
      </p>

      <p><strong>Main Topic:</strong>
        ${escapeHTML(revised.main_topic)}
      </p>

      <p><strong>Category:</strong>
        ${escapeHTML(revised.category)}
      </p>

      ${videoUrl ? `
        <p>
          <a href="${escapeHTML(videoUrl)}">
            Watch Original Video
          </a>
        </p>
      ` : ""}

      <hr>

      <h2>Previous Summary</h2>
      <p>${escapeHTML(originalSummary)}</p>

      <h2>Revised Executive Summary</h2>
      <p>${escapeHTML(revised.short_summary)}</p>

      <h2>Detailed Summary</h2>
      <p>${escapeHTML(revised.detailed_summary)}</p>

      <h2>Key Points</h2>
      ${htmlList(revised.key_points)}

      <h2>Important Insights</h2>
      ${htmlList(revised.important_insights)}

      <h2>Actionable Takeaways</h2>
      ${htmlList(revised.actionable_takeaways)}

      <h2>Keywords</h2>
      <p>${escapeHTML(revised.keywords.join(", "))}</p>

      <h2>Conclusion</h2>
      <p>${escapeHTML(revised.conclusion)}</p>

      <div style="
        background:#fff8e1;
        padding:18px;
        border-radius:8px;
        margin-top:25px;
      ">
        <strong>Second Human Review</strong>
        <p>
          Please compare the revised summary
          with the original video and approve
          or reject the updated report.
        </p>
      </div>

      <p style="
        font-size:12px;
        color:#888;
        margin-top:30px;
      ">
        AI-generated research report.
        Human verification required.
      </p>

    </div>
  </div>`;

  // Plain text for Gmail Approval Node
  const emailText = `
YOUTUBE SUMMARY — SECOND HUMAN REVIEW

VIDEO:
${title}

VIDEO URL:
${videoUrl}

MAIN TOPIC:
${revised.main_topic}

CATEGORY:
${revised.category}

PREVIOUS SUMMARY:
${originalSummary}

REVISED SUMMARY:
${revised.short_summary}

DETAILED SUMMARY:
${revised.detailed_summary}

KEY POINTS:
${revised.key_points.map((p, i) =>
  `${i + 1}. ${p}`
).join("\n")}

IMPORTANT INSIGHTS:
${revised.important_insights.join("\n")}

ACTIONABLE TAKEAWAYS:
${revised.actionable_takeaways.join("\n")}

KEYWORDS:
${revised.keywords.join(", ")}

CONCLUSION:
${revised.conclusion}

Please review the revised report and
select Approve or Reject.
`.trim();

  return {
    json: {
      ...revised,

      original_summary: originalSummary,

      key_points_text:
        revised.key_points.join("\n"),

      keywords_text:
        revised.keywords.join(", "),

      insights_text:
        revised.important_insights.join("\n"),

      review_status: "Pending Reapproval",
      revision_number: 1,

      validation_status: "Validated",
      processed_at: new Date().toISOString(),

      email_subject:
        `Reapproval Required: ${revised.main_topic}`,

      email_html: emailHTML,
      email_text: emailText
    }
  };
});

const items = $input.all();

return items.map(item => {

  const videoUrl = String(
    item.json["Enter your video Url"] || ""
  ).trim();

  let videoId = null;

  // Short YouTube URL
  const shortMatch = videoUrl.match(
    /youtu\.be\/([a-zA-Z0-9_-]{11})/
  );

  // Standard YouTube URL
  const watchMatch = videoUrl.match(
    /[?&]v=([a-zA-Z0-9_-]{11})/
  );

  // Shorts, Embed and Live URLs
  const pathMatch = videoUrl.match(
    /youtube(?:-nocookie)?\.com\/(?:shorts|embed|live|v)\/([a-zA-Z0-9_-]{11})/
  );

  videoId = shortMatch?.[1] ||
            watchMatch?.[1] ||
            pathMatch?.[1];

  // Validate
  if (!videoId) {
    throw new Error("Invalid YouTube Video URL");
  }

  return {
    json: {
      videoId: videoId
    }
  };

});
